                        </tbody></table></div><?php else: ?><div class="empty-state"><span class="empty-icon">⌁</span><strong><?= $user['role'] === 'user' ? match ($reportTab) { 'messages' => 'No report conversations yet', 'history' => 'No completed reports yet', default => 'No ongoing reports' } : ($reportTab === 'history' ? 'No resolved reports' : 'No ongoing reports') ?></strong><p><?= $user['role'] === 'user' ? match ($reportTab) { 'messages' => 'Messages will appear when a worker is assigned to one of your reports.', 'history' => 'Resolved and not approved reports will appear here.', default => 'Submit a road hazard to start tracking its progress.' } : ($user['role'] === 'worker' ? 'Reports assigned to you will appear here.' : 'Incoming community reports will appear here.') ?></p><?php if ($user['role'] === 'user' && $reportTab === 'ongoing'): ?><a class="button button-primary" href="index.php?view=add_report">Add a report <span>↗</span></a><?php endif; ?></div><?php endif; ?>
