                        <?php if ($displayJobRows): ?><div class="job-list"><?php foreach ($displayJobRows as $job): $jobMessages = $conversationMessages[(int) $job['report_id']] ?? []; $latestJobMessageId = $jobMessages ? (int) $jobMessages[count($jobMessages) - 1]['id'] : 0; ?><article class="job-card"><div class="job-card-top"><span class="record-id">JOB / <?= e($job['public_id']) ?></span><span class="status-pill <?= status_class($job['status']) ?>"><?= e(status_label($job['status'])) ?></span></div><h3><?= e($job['title']) ?></h3><p class="job-location"><span>⌖</span> <?= e($job['road_location_label']) ?> <i>·</i> <?= e($job['category']) ?></p><?php if (!empty($job['photo_path'])): ?><img class="proof-image job-proof-image image-preview" src="index.php?image=<?= e($job['photo_path']) ?>" alt="Hazard photo proof" loading="lazy" role="button" tabindex="0" aria-label="View full hazard photo"><?php endif; ?><div class="job-meta"><span>Reported by <strong><?= e($job['reporter_name']) ?></strong></span><span>Updated <?= e(date('M j, Y', strtotime($job['updated_at']))) ?></span><?php if (!empty($job['worker_name'])): ?><span>Assigned to <strong><?= e($job['worker_name']) ?></strong></span><?php endif; ?></div>
                                <?php if ($isManager && $job['status'] === 'pending_assignment'): ?><form method="post" class="assign-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="assign_job"><input type="hidden" name="job_id" value="<?= (int) $job['id'] ?>"><select name="worker_id" required aria-label="Choose worker"><option value="">Select a worker</option><?php foreach ($workers as $worker): ?><option value="<?= (int) $worker['id'] ?>"><?= e($worker['name']) ?></option><?php endforeach; ?></select><button class="button button-small button-primary" type="submit" <?= $workers ? '' : 'disabled' ?>>Assign job <span>↗</span></button></form><?php endif; ?>
                                <?php if (in_array($job['status'], ['assigned', 'in_progress', 'pending_user_verification', 'completed'], true)): ?><section class="conversation-section"><details class="conversation-disclosure"><summary><span class="conversation-show-label">Show messages</span><span class="conversation-hide-label">Hide messages</span><span class="conversation-count" data-conversation-count><?= count($jobMessages) ?></span></summary><div class="conversation-content"><div class="conversation-thread" id="live-conversation-<?= (int) $job['report_id'] ?>" aria-label="Conversation for report <?= e($job['public_id']) ?>" aria-live="polite" data-live-report-id="<?= (int) $job['report_id'] ?>" data-last-message-id="<?= $latestJobMessageId ?>"><?php foreach ($jobMessages as $message): ?><article class="conversation-message <?= (int) $message['sender_user_id'] === (int) $user['id'] ? 'is-mine' : '' ?>"><div class="conversation-message-meta"><strong><?= (int) $message['sender_user_id'] === (int) $user['id'] ? 'You' : e($message['sender_name']) ?></strong><span><?= e(date('M j, g:i a', strtotime($message['created_at']))) ?></span></div><p><?= nl2br(e($message['message'])) ?></p><?php if (!empty($message['photo_path'])): ?><img class="proof-image conversation-image image-preview" src="index.php?image=<?= e($message['photo_path']) ?>" alt="Conversation photo" loading="lazy" role="button" tabindex="0" aria-label="View full conversation photo"><?php endif; ?></article><?php endforeach; ?><?php if (!$jobMessages): ?><p class="muted conversation-empty">No progress messages yet.</p><?php endif; ?></div><?php if (!in_array($user['role'], ['admin', 'super_admin'], true) && $job['status'] !== 'completed'): ?><form method="post" enctype="multipart/form-data" class="conversation-compose"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="send_message"><input type="hidden" name="return_tab" value="<?= e($jobTab) ?>"><input type="hidden" name="job_id" value="<?= (int) $job['id'] ?>"><label class="sr-only" for="reply-job-<?= (int) $job['id'] ?>">Message to reporter</label><textarea id="reply-job-<?= (int) $job['id'] ?>" name="message" rows="2" maxlength="2000" placeholder="Message the reporter…"></textarea><label class="image-upload-control">Add photo<input type="file" name="conversation_image" accept="image/jpeg,image/png,image/webp"></label><button class="button button-small button-primary" type="submit">Send</button><p class="conversation-send-status" role="status" aria-live="polite" hidden data-message-status></p></form><?php endif; ?></div></details></section><?php endif; ?>
                                <?php if ($user['role'] === 'worker' && in_array($job['status'], ['assigned', 'in_progress'], true)): ?><details class="job-update"><summary><?= $job['status'] === 'assigned' ? 'Start / update work' : 'Update job' ?> <span>＋</span></summary><form method="post" enctype="multipart/form-data" class="form-stack"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="worker_update"><input type="hidden" name="job_id" value="<?= (int) $job['id'] ?>"><label>Field notes<textarea name="worker_notes" rows="2" maxlength="1000" placeholder="Describe the progress made for the reporter."></textarea></label><label>Progress photo (optional)<input type="file" name="progress_image" accept="image/jpeg,image/png,image/webp"><small>JPEG, PNG, or WebP; maximum 5 MB.</small></label><div class="inline-actions"><button class="button button-small button-quiet" name="status" value="in_progress">Save progress</button><button class="button button-small button-primary" name="status" value="pending_user_verification">Mark complete</button></div></form></details><?php elseif ($job['status'] === 'pending_user_verification'): ?><p class="verification-hint">Work is with the reporter for on-site verification.</p><?php endif; ?>
