                        <div class="surface table-surface account-table"><div class="section-heading"><div><p class="eyebrow">TEAM DIRECTORY</p><h2>Managed accounts</h2></div><span class="table-count"><?= count($accountRows) ?> people</span></div><div class="table-scroll"><table><thead><tr><th>Account</th><th>Role</th><th>Joined</th><th>Access</th><th>Manage</th></tr></thead><tbody><?php foreach ($accountRows as $account): ?><tr><td><strong><?= e($account['name']) ?></strong><small><?= e($account['email']) ?></small></td><td><span class="role-tag role-<?= e($account['role']) ?>"><?= e(ucfirst($account['role'])) ?></span></td><td><?= e(date('M j, Y', strtotime($account['created_at']))) ?></td><td><span class="access-state <?= $account['is_active'] ? 'access-on' : 'access-off' ?>"><?= $account['is_active'] ? 'Active' : 'Paused' ?></span></td><td><div class="account-actions"><details class="account-edit"><summary>Edit</summary><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update_account"><input type="hidden" name="user_id" value="<?= (int) $account['id'] ?>"><input name="name" value="<?= e($account['name']) ?>" required maxlength="120" aria-label="Name"><input type="email" name="email" value="<?= e($account['email']) ?>" required maxlength="190" aria-label="Email"><?php if ($user['role'] === 'super_admin'): ?><select name="role" aria-label="Role"><option value="admin" <?= $account['role'] === 'admin' ? 'selected' : '' ?>>Admin</option><option value="worker" <?= $account['role'] === 'worker' ? 'selected' : '' ?>>Worker</option><option value="user" <?= $account['role'] === 'user' ? 'selected' : '' ?>>Reporter</option></select><?php else: ?><input type="hidden" name="role" value="<?= e($account['role']) ?>"><?php endif; ?><input type="password" name="password" minlength="10" placeholder="New password (optional)" aria-label="New password"><button class="button button-small button-primary" type="submit">Save changes</button></form></details><?php if ($account['is_active']): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="account_status"><input type="hidden" name="user_id" value="<?= (int) $account['id'] ?>"><button class="text-button" name="operation" value="deactivate">Pause</button></form><?php else: ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="account_status"><input type="hidden" name="user_id" value="<?= (int) $account['id'] ?>"><button class="text-button" name="operation" value="activate">Restore</button></form><?php endif; ?><form method="post" data-confirm="Remove this account? Historical records will remain."><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="account_status"><input type="hidden" name="user_id" value="<?= (int) $account['id'] ?>"><button class="text-button text-danger" name="operation" value="delete">Remove</button></form></div></td></tr><?php endforeach; ?></tbody></table></div></div></section>
                <?php elseif ($view === 'notifications'): ?>
                    <section class="surface table-surface"><div class="section-heading"><div><p class="eyebrow">KEEP IN THE LOOP</p><h2>Recent notifications</h2></div><form method="post" id="mark-notifications-read"<?= $unreadCount ? '' : ' hidden' ?>><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="mark_notifications_read"><button class="button button-small button-quiet">Mark all read</button></form></div>
                        <div id="notification-feed" aria-live="polite"><?php if ($notifications): ?><div class="notification-list"><?php foreach ($notifications as $notification): ?><article class="notification-row <?= $notification['read_at'] ? '' : 'notification-unread' ?>" data-notification-id="<?= (int) $notification['id'] ?>" data-notification-read="<?= $notification['read_at'] ? 'true' : 'false' ?>"><a class="notification-link" href="index.php?view=<?= $user['role'] === 'user' ? 'reports&amp;tab=messages' : 'jobs' ?>"><span class="notification-symbol"><?= $notification['read_at'] ? '·' : '!' ?></span><span class="notification-copy"><strong><?= e($notification['message']) ?></strong><small><?= e($notification['title']) ?> · <?= e(date('M j, Y · g:i a', strtotime($notification['created_at']))) ?></small><?php if (!empty($notification['photo_path'])): ?><img class="activity-image image-preview" src="index.php?image=<?= e($notification['photo_path']) ?>" alt="Progress photo" loading="lazy" role="button" tabindex="0" aria-label="View full progress photo"><?php endif; ?></span><b>↗</b></a><?php if (!$notification['read_at']): ?><form method="post" class="notification-read-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="mark_notification_read"><input type="hidden" name="notification_id" value="<?= (int) $notification['id'] ?>"><button class="button button-small button-quiet" type="submit">Mark read</button></form><?php else: ?><span class="notification-read-status">Read</span><?php endif; ?></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><span class="empty-icon">◉</span><strong>You are all caught up</strong><p>Updates about your reports and work will appear here.</p></div><?php endif; ?></div>
